#!/usr/bin/env python3
import sys, os, re, gzip, json, csv, codecs, datetime
import xml.etree.ElementTree as ET
from decimal import Decimal, ROUND_HALF_UP, InvalidOperation

ORDER = ["central", "south", "east", "river", "north", "west", "harbor", "lakeside"]
FACT = {"kg": Decimal(1), "g": Decimal("0.001"), "lb": Decimal("0.45359237"),
        "oz": Decimal("0.028349523125")}
MONTHS = {m: i + 1 for i, m in enumerate(
    "jan feb mar apr may jun jul aug sep oct nov dec".split())}
COUNTED = {"delivered", "delivered_late"}


def norm_status(s):
    return re.sub(r"[\s\-]+", "_", (s or "").strip().lower())


def sid(s):
    m = re.search(r"SH\D*(\d+)", s or "", re.I)
    return int(m.group(1)) if m else None


def decode(b):
    if b[:2] == b"\x1f\x8b":
        b = gzip.decompress(b)
    if b[:3] == b"\xef\xbb\xbf":
        return b[3:].decode("utf-8", "replace")
    if b[:2] in (b"\xff\xfe", b"\xfe\xff"):
        return b.decode("utf-16", "replace")
    enc = "utf-8"
    head = b[:600].decode("latin-1")
    m = re.search(r"^#\s*charset\s*:\s*([\w.\-]+)", head, re.I | re.M)
    if m:
        try:
            codecs.lookup(m.group(1))
            enc = m.group(1)
        except LookupError:
            pass
    return b.decode(enc, "replace")


# ---- dates ----
def parse_date(v, form):
    """Return (date) in UTC from a string."""
    v = v.strip()
    m = re.fullmatch(r"(\d{4})-(\d\d)-(\d\d)[T ](\d\d):(\d\d)(?::(\d\d)(?:\.\d+)?)?\s*(Z|[+-]\d\d:?\d\d)?", v, re.I)
    if m:
        y, mo, d, h, mi = map(int, m.groups()[:5])
        s = int(m.group(6) or 0)
        dt = datetime.datetime(y, mo, d, h, mi, s)
        tz = m.group(7)
        if tz and tz.upper() != "Z":
            sign = 1 if tz[0] == "+" else -1
            t = tz[1:].replace(":", "")
            off = datetime.timedelta(hours=int(t[:2]), minutes=int(t[2:]))
            dt = dt - sign * off
        return dt.date()
    m = re.fullmatch(r"(\d{1,2}) ([A-Za-z]{3})[a-z]* (\d{4})", v)
    if m:
        return datetime.date(int(m.group(3)), MONTHS[m.group(2).lower()], int(m.group(1)))
    f = (form or "iso").strip().lower()
    if f == "serial" or re.fullmatch(r"\d{5}(\.\d+)?", v) and f == "serial":
        return datetime.date(1899, 12, 31) + datetime.timedelta(days=int(float(v)) - (0 if int(float(v)) < 60 else 1) + 0) if False else \
            datetime.date(1899, 12, 30) + datetime.timedelta(days=int(float(v))) if int(float(v)) >= 60 else \
            datetime.date(1899, 12, 31) + datetime.timedelta(days=int(float(v)) - 1)
    if re.fullmatch(r"\d{8}", v):
        return datetime.date(int(v[:4]), int(v[4:6]), int(v[6:]))
    if re.fullmatch(r"\d{7}", v):
        return datetime.date(int(v[:4]), 1, 1) + datetime.timedelta(days=int(v[4:]) - 1)
    p = [int(x) for x in re.findall(r"\d+", v)]
    if len(p) < 3:
        raise ValueError("date " + v)
    if f in ("iso", "ymd", "yyyy-mm-dd"):
        y, mo, d = p[:3]
    elif f in ("dmy", "dd/mm/yyyy", "dd-mm-yyyy", "dd.mm.yyyy"):
        d, mo, y = p[:3]
    elif f in ("mm/dd/yyyy", "mdy"):
        mo, d, y = p[:3]
    else:
        if p[0] > 31:
            y, mo, d = p[:3]
        else:
            d, mo, y = p[:3]
    return datetime.date(y, mo, d)


def parse_serial(v):
    n = int(float(v))
    return datetime.date(1899, 12, 31) + datetime.timedelta(days=n - 1 if n < 60 else n - 1 - 0) \
        if n < 60 else datetime.date(1899, 12, 30) + datetime.timedelta(days=n)


_pd = parse_date


def parse_date(v, form):  # wrapper handling serial cleanly
    if (form or "").strip().lower() == "serial" and re.fullmatch(r"\d+(\.\d+)?", v.strip()):
        return parse_serial(v.strip())
    return _pd(v, form)


# ---- weights ----
def to_dec(s, style):
    s = s.strip()
    if style == "west":
        s = s.replace(".", "").replace(",", ".")
    else:
        s = s.replace(",", "")
    return Decimal(s)


def weight_kg(text, style, unit):
    m = re.fullmatch(r"\s*([0-9.,]+)\s*([A-Za-z]*)\s*", text)
    if not m:
        raise ValueError("weight " + text)
    n = to_dec(m.group(1), style)
    u = (m.group(2) or unit or "kg").lower()
    return n * FACT[u]


# ---- record: dict(id, type, kg, date, status) ----
def rtype(t):
    t = (t or "").strip().lower()
    if t in ("c", "cor", "corr", "correction", "amend", "amendment"):
        return "C"
    if t in ("v", "void"):
        return "V"
    return "N"


DELIM = {"east": ",", "lakeside": ",", "river": "\t", "west": ";", "harbor": "|"}
COLS = {
    "east": {"id", "type", "shipped", "gross", "net", "status", "note"},
    "lakeside": {"id", "kind", "booked", "shipped", "gross_kg", "net_kg", "status"},
    "river": {"t", "ref", "shipped", "weight", "status"},
    "west": {"id", "typ", "shipped", "weight", "status", "note"},
    "harbor": {"rec", "ref", "date", "weight", "state"},
}
HARBOR_ST = {"dlv": "delivered", "dll": "delivered_late", "can": "cancelled",
             "ret": "returned", "hld": "held"}
FW_ST = {"D": "delivered", "L": "delivered_late", "C": "cancelled", "R": "returned", "H": "held"}


def split_logical(text, quoting):
    """Yield ('comment', line) or ('row', line_text) handling quoted multiline."""
    lines = text.split("\n")
    buf = None
    for ln in lines:
        if buf is None:
            l = ln.rstrip("\r")
            if not l.strip():
                continue
            if l.startswith("#"):
                yield ("comment", l)
                continue
            buf = ln
        else:
            buf += "\n" + ln
        if not quoting or buf.count('"') % 2 == 0:
            yield ("row", buf.rstrip("\r"))
            buf = None
    if buf is not None and buf.strip():
        yield ("row", buf)


def parse_delimited(dep, text):
    d = DELIM[dep]
    quoting = d == ","
    seq = None
    dirs = {}
    hdr = None
    recs = []
    cols = COLS[dep]
    if dep == "harbor":
        m = re.search(r"seq\s*=\s*(\d+)", text.split("\n", 1)[0])
        if m:
            seq = int(m.group(1))

    def colnorm(c):
        c = c.strip().lower()
        return c
    for kind, l in split_logical(text, quoting):
        if kind == "comment":
            m = re.match(r"#\s*([A-Za-z][\w ]*?)\s*:\s*(.*?)\s*$", l)
            if m:
                name = re.sub(r"\s+", " ", m.group(1).lower())
                dirs[name] = m.group(2)
                if name == "seq":
                    try:
                        seq = int(m.group(2))
                    except ValueError:
                        pass
            continue
        if quoting:
            row = next(csv.reader([l], delimiter=d))
        else:
            row = l.split(d)
        names = [colnorm(c) for c in row]
        if all(n in cols for n in names) and len(names) >= 2:
            hdr = names
            continue
        if hdr is None:
            continue
        row = [c.strip() if i != len(row) else c for i, c in enumerate(row)]
        rd = {}
        row_unit = None
        if len(row) > len(hdr):
            # row carries its own weight unit right after the weight column
            wi = [i for i, h in enumerate(hdr) if h.startswith("gross") or h == "weight"]
            wi = wi[0] if wi else None
            if wi is not None and len(row) == len(hdr) + 1:
                row_unit = row[wi + 1].strip().lower()
                row = row[:wi + 1] + row[wi + 2:]
        row = row + [""] * (len(hdr) - len(row))
        for h, v in zip(hdr, row):
            rd[h] = v
        rec = build_delim(dep, rd, dirs, row_unit)
        if rec:
            recs.append(rec)
    return seq, recs


def dir_unit(dirs):
    for k in ("weight unit", "unit"):
        if k in dirs:
            m = re.match(r"\s*([A-Za-z]+)", dirs[k])
            if m and m.group(1).lower() in FACT:
                return m.group(1).lower()
    return None


def build_delim(dep, r, dirs, row_unit):
    idf = {"east": "id", "lakeside": "id", "river": "ref", "west": "id", "harbor": "ref"}[dep]
    n = sid(r.get(idf, ""))
    if n is None:
        return None
    tf = {"east": "type", "lakeside": "kind", "river": "t", "west": "typ", "harbor": "rec"}[dep]
    t = rtype(r.get(tf))
    if t == "V":
        return {"n": n, "t": "V"}
    form = dirs.get("dates") or dirs.get("date format")
    if dep == "harbor":
        form = form or "iso"
    datev = r.get("date" if dep == "harbor" else "shipped", "")
    # weight
    wcol = None
    suffix = None
    for h in r:
        if h in ("weight", "gross") or h.startswith("gross_") or h.startswith("weight_"):
            wcol = h
            mm = re.search(r"_(kg|g|lb|oz)$", h)
            suffix = mm.group(1) if mm else None
            break
    unit = suffix or row_unit or dir_unit(dirs) or "kg"
    style = "west" if dep == "west" else "plain"
    if dep == "east":
        style = "east"
    try:
        kg = weight_kg(r[wcol], style, unit)
        date = parse_date(datev, form)
    except (ValueError, InvalidOperation, KeyError, TypeError):
        return None
    st = r.get("state" if dep == "harbor" else "status", "")
    if dep == "harbor":
        st = HARBOR_ST.get(st.strip().lower(), st)
    return {"n": n, "t": t, "kg": kg, "date": date, "st": norm_status(st)}


def parse_json(text):
    import json as J
    seq = None
    recs = []
    for l in text.split("\n"):
        l = l.strip()
        if not l:
            continue
        try:
            v = J.loads(l)
        except ValueError:
            continue
        objs = v if isinstance(v, list) else [v]
        for o in objs:
            if not isinstance(o, dict):
                continue
            if "meta" in o and isinstance(o["meta"], dict):
                try:
                    seq = int(o["meta"].get("seq"))
                except (TypeError, ValueError):
                    pass
                continue
            n = sid(str(o.get("id", "")))
            if n is None:
                continue
            t = rtype(o.get("kind"))
            if t == "V":
                recs.append({"n": n, "t": "V"})
                continue
            kg = None
            for k, val in o.items():
                m = re.fullmatch(r"weight_(kg|g|lb|oz)", k)
                if m and val is not None:
                    kg = Decimal(str(val)) * FACT[m.group(1)]
                    break
            if kg is None and "weight" in o:
                kg = Decimal(str(o["weight"])) * FACT[str(o.get("unit", "kg")).lower()]
            try:
                date = parse_date(str(o.get("shipped_at")), "iso")
            except Exception:
                continue
            recs.append({"n": n, "t": t, "kg": kg, "date": date,
                         "st": norm_status(str(o.get("status", "")))})
    return seq, recs


def parse_xml(b_text):
    root = ET.fromstring(b_text.encode("utf-8") if False else re.sub(r"^<\?xml[^>]*\?>", "", b_text.lstrip("\ufeff").lstrip()))
    seq = None
    try:
        seq = int(root.get("seq"))
    except (TypeError, ValueError):
        pass
    runit = (root.get("weight-unit") or "kg").lower()
    recs = []
    for e in root.iter("shipment"):
        n = sid(e.get("id", ""))
        if n is None:
            continue

        def val(name):
            c = e.find(name)
            if c is not None:
                return c, (c.text or "").strip()
            if e.get(name) is not None:
                return None, e.get(name).strip()
            return None, None
        t = rtype(e.get("type"))
        if t == "V":
            recs.append({"n": n, "t": "V"})
            continue
        wc, wt = val("weight")
        unit = ((wc.get("unit") if wc is not None else None) or e.get("weight-unit") or e.get("unit") or runit).lower()
        _, sh = val("shipped")
        _, st = val("status")
        try:
            kg = weight_kg(wt, "plain", unit)
            date = parse_date(sh, "iso")
        except Exception:
            continue
        recs.append({"n": n, "t": t, "kg": kg, "date": date, "st": norm_status(st)})
    return seq, recs


FW = {
    "FW1": (42, dict(type=(9, 10), shipped=(10, 17), weight=(17, 25), status=(25, 26), id=(0, 9)), "doy", Decimal("0.001")),
    "FW2": (43, dict(type=(0, 1), id=(1, 10), shipped=(10, 18), weight=(18, 26), status=(26, 27)), "ymd", Decimal("0.01")),
    "FW3": (41, dict(id=(0, 9), shipped=(9, 16), type=(16, 17), weight=(17, 24), status=(24, 25)), "doy", FACT["lb"] / 10),
}


def parse_fw(text):
    seq = None
    layout = None
    recs = []
    bylen = {v[0]: k for k, v in FW.items()}
    for l in text.split("\n"):
        l = l.rstrip("\r")
        if not l.strip():
            continue
        if l.startswith("#LAYOUT"):
            layout = l.split()[1].strip().upper()
            continue
        if l.startswith("#SEQ"):
            try:
                seq = int(l.split()[1])
            except (ValueError, IndexError):
                pass
            continue
        if l.startswith("#") or l.startswith("\x0c"):
            continue
        name = bylen.get(len(l))
        if name is None:
            continue
        ln, pos, kind, mult = FW[name]
        f = {k: l[a:b] for k, (a, b) in pos.items()}
        n = sid(f["id"])
        if n is None:
            continue
        t = rtype(f["type"])
        if t == "V":
            recs.append({"n": n, "t": "V"})
            continue
        try:
            sh = f["shipped"].strip()
            if kind == "doy":
                date = datetime.date(int(sh[:4]), 1, 1) + datetime.timedelta(days=int(sh[4:]) - 1)
            else:
                date = datetime.date(int(sh[:4]), int(sh[4:6]), int(sh[6:8]))
            kg = Decimal(int(f["weight"])) * mult
        except ValueError:
            continue
        recs.append({"n": n, "t": t, "kg": kg, "date": date,
                     "st": norm_status(FW_ST.get(f["status"].strip().upper(), f["status"]))})
    return seq, recs


def main():
    data, out = sys.argv[1], sys.argv[2]
    exports = {}
    for name in sorted(os.listdir(data)):
        p = os.path.join(data, name)
        if not os.path.isfile(p):
            continue
        dep = name.split("-")[0].lower()
        with open(p, "rb") as fh:
            text = decode(fh.read())
        exports.setdefault(dep, [])
        if dep == "central":
            seq, recs = parse_xml(text)
        elif dep == "north":
            seq, recs = parse_json(text)
        elif dep == "south":
            seq, recs = parse_fw(text)
        elif dep in DELIM:
            seq, recs = parse_delimited(dep, text)
        else:
            continue
        exports[dep].append((seq if seq is not None else -1, name, recs))

    corrections = resends = 0
    current = {}
    for dep, lst in exports.items():
        lst.sort(key=lambda x: (x[0], x[1]))
        cur = {}
        for _, _, recs in lst:
            for r in recs:
                n = r["n"]
                if r["t"] == "N":
                    if n in cur:
                        resends += 1
                    else:
                        cur[n] = r
                elif r["t"] == "C":
                    cur[n] = r
                    corrections += 1
                else:
                    cur.pop(n, None)
                    corrections += 1
        current[dep] = cur

    rank = {d: i for i, d in enumerate(ORDER)}
    owners = {}
    for dep, cur in current.items():
        for n in cur:
            owners.setdefault(n, []).append(dep)
    handovers = sum(1 for v in owners.values() if len(v) > 1)

    deps = {d: [0, Decimal(0)] for d in sorted(exports)}
    months = {}
    for n, ds in owners.items():
        dep = min(ds, key=lambda d: rank.get(d, 99))
        r = current[dep][n]
        if r["st"] not in COUNTED:
            continue
        deps[dep][0] += 1
        deps[dep][1] += r["kg"]
        mk = "%04d-%02d" % (r["date"].year, r["date"].month)
        m = months.setdefault(mk, [0, Decimal(0)])
        m[0] += 1
        m[1] += r["kg"]

    def fmt(v):
        return float(v[1].quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))
    res = {
        "depots": {d: {"shipments": v[0], "total_kg": fmt(v)} for d, v in deps.items()},
        "months": {k: {"shipments": months[k][0], "total_kg": fmt(months[k])} for k in sorted(months)},
        "corrections_applied": corrections,
        "resends_dropped": resends,
        "handovers": handovers,
    }
    with open(out, "w") as fh:
        json.dump(res, fh, indent=2)
        fh.write("\n")


if __name__ == "__main__":
    main()
